function [intercept_point, candidates] = UVplaneintercept(hoop_verts, curve)
% finds the intercept between the curve and the surface generated by
% hoop_verts and its midpoint
%

% make midpoint 
midpoint = mean(hoop_verts, 1);

% find intersections between curve and triangle
num_V = size(hoop_verts,1);
num_c = size(curve, 1);
candidates = [];
for k = 1:num_V
    p1 = hoop_verts(k,:)-midpoint;
    if k == num_V
        p2 = hoop_verts(1,:)-midpoint;
    else
        p2 = hoop_verts(k+1,:)-midpoint;
    end
    normal = cross(p1,p2);
    sign_prev = sign(dot(curve(1,:)-midpoint, normal));
    for j = 2:num_c
        c = sign(dot(curve(j,:)-midpoint, normal));
        if sign_prev * c < 0
            x1 = curve(j-1,:)-midpoint;
            x2 = curve(j,:)-midpoint;
            x1n = dot(x1, normal);
            x2n = dot(x2, normal);
            us = (x2n*x1 - x1n * x2) / (x2n - x1n);
            % check if in the slice
            if dot(normal, cross(us, p1)) * dot(normal, cross(us, p2)) < 0
                candidates(end+1,:) = us+midpoint;
            end
        end
        sign_prev = c;
    end
end
% find the closest candidate to the midpoint (because might be multiple
% intersection of the plane
% Calculate the distances from the midpoint to each candidate
if size(candidates,1)>0
    
    closest = zeros(size(candidates,1),1);
    %size(candidates,1)
    for k = 1:size(candidates,1)
        closest(k) = min(vecnorm(candidates(k,:)- hoop_verts, 2,2));
    end
    [~, minIndex] = min(closest);
    % Find the index of the closest candidate
    %distances = vecnorm(candidates - midpoint, 2, 2);
    %[~, minIndex] = min(distances);
    
    % Assign the closest candidate to the intercept point
    intercept_point = candidates(minIndex, :);
else
    intercept_point = []; % No intersection found
end

end


